html, body { margin: 0px; padding: 0px; }
body { font-family: system-ui, -apple-system, "Segoe UI", sans-serif; text-size-adjust: 100%; }
:root { padding-top: env(safe-area-inset-top,0px); padding-bottom: env(safe-area-inset-bottom,0px); }
img { max-width: 100%; }
[hidden] { display: none !important; }

:root { --night: #0d120f; --panel: #161c17; --panel2: #1e261f; --line: #2c372d; --ink: #ece6d3; --muted: #98a191; --ember: #e98b3d; --ember-d: #a85d22; --blood: #cf4b3f; --moss: #86a85c; --frost: #9fc3d6; --f-display: "Russo One","Arial Black",system-ui,sans-serif; --f-body: "Rubik",system-ui,-apple-system,"Segoe UI",sans-serif; color-scheme: dark; }
html, body { height: 100%; overflow: hidden; }
[hidden] { display: none !important; }
#win { position: fixed; inset: 0px; z-index: 40; background: rgba(6, 8, 4, 0.8); display: flex; align-items: center; justify-content: center; padding: 16px; }
.win-card { border-color: rgb(244, 199, 102); }
.win-card h2 { color: rgb(244, 199, 102); }
.win-note { font-size: 12px; color: var(--muted); }
.win-b { display: grid; gap: 8px; }
#ngBtn { background: rgb(106, 74, 16); border-color: rgb(244, 199, 102); }
.item.itm { border-left: 3px solid var(--rc); grid-template-columns: auto minmax(0px, 1fr) auto; align-items: start; }
@media (max-width: 640px) {
  .item.itm { grid-template-columns: auto minmax(0px, 1fr); }
  .item.itm .itm-b { grid-column: 1 / -1; flex-flow: wrap; }
}
.itm h3 { color: var(--rc); }
.itm.better { box-shadow: rgba(126, 224, 126, 0.45) 0px 0px 0px 1px inset; background: linear-gradient(90deg,rgba(126,224,126,.08),transparent 60%),var(--panel2); }
.itm-ico { width: 48px; height: 48px; border-radius: 8px; display: grid; place-items: center; background: radial-gradient(circle,color-mix(in srgb,var(--rc) 22%,transparent),rgba(0,0,0,.25)); border: 1px solid color-mix(in srgb,var(--rc) 45%,transparent); }
.cmp { font-size: 12px; }
.cmp .up, .cmp b.up { color: rgb(126, 224, 126); }
.cmp .dn, .cmp b.dn { color: rgb(224, 112, 112); }
.vs { color: var(--muted); font-size: 11px; }
.stats-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 6px; background: var(--panel2); border: 1px solid var(--line); border-radius: 10px; padding: 10px; }
.stats-grid div { display: grid; gap: 2px; min-width: 0px; }
.stats-grid small { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; }
.stats-grid b { font-size: 13px; font-variant-numeric: tabular-nums; }
.itm-b { display: flex; flex-direction: column; gap: 6px; align-items: stretch; }
.itm.setit .itm-ico { position: relative; border: 2px solid transparent; background: linear-gradient(#141b16,#141b16) padding-box,conic-gradient(from var(--sa,0deg),var(--rc),#f4c766,var(--rc),#fff3c0,var(--rc)) border-box; box-shadow: 0 0 14px var(--rc); animation: 6s linear 0s infinite normal none running setspin; }
@property --sa { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@keyframes setspin { 
  100% { --sa: 360deg; }
}
.itm.setit h3 { text-shadow: 0 0 8px var(--rc); }
.buy.sec { background: var(--panel); color: var(--ink); border: 1px solid var(--line); }
.buy .ico { vertical-align: -0.2em; }
