#questList { list-style: none; margin: 2px 0px 0px; padding: 0px; display: grid; gap: 5px; }
#questList li { display: grid; grid-template-columns: 1fr auto; gap: 0px 6px; position: relative; padding-bottom: 4px; line-height: 1.25; }
#questList li b { font-variant-numeric: tabular-nums; color: var(--ink); }
#questList li i { grid-column: 1 / -1; height: 3px; background: var(--moss); border-radius: 2px; display: block; max-width: 100%; }
#questList li small { grid-column: 1 / -1; color: var(--muted); font-size: 10px; display: flex; align-items: center; gap: 3px; }
#questList .ico { width: 1em; height: 1em; }
#tut { position: fixed; inset: 0px; z-index: 34; background: rgba(5, 8, 6, 0.55); display: flex; align-items: center; justify-content: center; padding: 16px; }
