.cls-card { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; text-align: left; background: rgb(20, 26, 21); border: 2px solid var(--cc); border-radius: 14px; padding: 14px; color: var(--ink); font: inherit; cursor: pointer; }
.cls-card:hover { background: rgb(27, 35, 28); }
.cls-card img { align-self: center; border-radius: 10px; width: 120px; height: 120px; }
.cls-card b { font-size: 22px; }
.cls-card small { color: var(--muted); margin-top: -6px; }
.cls-card span { font-size: 12px; line-height: 1.4; }
.cls-card em { display: block; font-style: normal; color: var(--muted); font-size: 11px; font-weight: 700; }
.cls-card i { align-self: stretch; margin-top: 6px; text-align: center; font-style: normal; font-weight: 800; background: var(--cc); color: rgb(20, 17, 14); border-radius: 8px; padding: 9px; }
.note { font-size: 12px; color: var(--muted); line-height: 1.5; margin: 0px; }
.warn { color: var(--blood); font-size: 12px; margin: 0px; }
textarea { width: 100%; box-sizing: border-box; min-height: 70px; background: rgb(11, 15, 12); color: var(--ink); border: 1px solid var(--line); border-radius: 8px; font: 12px ui-monospace, Menlo, monospace; padding: 8px; resize: vertical; }
.zone { display: grid; gap: 4px; }
.zone .bar > i { background: var(--moss); }
@media (max-width: 520px) {
  #quests { top: calc(104px + env(safe-area-inset-top,0px)); width: min(160px, -230px + 100vw); font-size: 10px; }
  #questList li small { display: none; }
  #toasts { --toast-top: calc(204px + env(safe-area-inset-top,0px)); }
  #stats { min-width: 150px; padding: 8px 10px; font-size: 12px; }
  #mini { width: 84px; height: 84px; }
  #clock { top: calc(150px + env(safe-area-inset-top,0px)); left: 12px; transform: none; padding: 4px 10px; }
  #help { display: none; }
}
.touch button { touch-action: manipulation; -webkit-tap-highlight-color: transparent; }
.touch #help { display: none; }
.touch .btns { right: calc(10px + env(safe-area-inset-right,0px)); bottom: calc(12px + env(safe-area-inset-bottom,0px)); width: 230px; height: 190px; display: block; pointer-events: none; }
.touch .btns .gbtn { position: absolute; pointer-events: auto; display: flex; align-items: center; justify-content: center; text-align: center; padding: 0px; line-height: 1.1; }
.touch #act, .touch #dashBtn, .touch #wpnBtn, .touch #potBtn, .touch #atkBtn { position: absolute; }
.touch #act { right: 0px; bottom: 0px; width: 100px; height: 100px; font-size: 15px; }
.touch #dashBtn { right: 110px; bottom: 6px; width: 66px; height: 66px; border-radius: 50%; font-size: 12px; }
.touch #dashBtn i { left: 12px; right: 12px; bottom: 10px; border-radius: 2px; max-width: 42px; width: auto !important; }
.touch #wpnBtn { right: 18px; bottom: 110px; width: 62px; height: 62px; border-radius: 50%; font-size: 12px; }
.touch #potBtn { right: 96px; bottom: 86px; width: 58px; height: 58px; border-radius: 50%; font-size: 13px; gap: 2px; }
.touch #potBtn .ico, .touch #atkBtn .ico { width: 20px; height: 20px; }
.touch #atkBtn { right: 162px; bottom: 96px; width: 58px; height: 58px; border-radius: 50%; font-size: 12px; gap: 1px; flex-direction: column; }
.touch #atkBtn small { font-size: 10px; }
.touch #campBtn { position: fixed; top: calc(104px + env(safe-area-inset-top,0px)); right: calc(10px + env(safe-area-inset-right,0px)); height: 44px; min-width: 92px; padding: 0px 14px; font-size: 14px; border-color: var(--ember); }
.touch #sndBtn { position: fixed; top: calc(154px + env(safe-area-inset-top,0px)); right: calc(10px + env(safe-area-inset-right,0px)); height: 36px; min-width: 92px; padding: 0px 10px; font-size: 11px; }
.touch #quests { top: calc(198px + env(safe-area-inset-top,0px)); right: calc(10px + env(safe-area-inset-right,0px)); width: min(200px, -220px + 100vw); font-size: 12px; }
.touch #questHead { font-size: 12px; padding: 6px 0px; }
.touch #questList li small { display: flex; }
.touch #stats { font-size: 13px; min-width: 170px; }
.touch .lbl { font-size: 11px; }
.touch #clock b { font-size: 15px; }
.touch #clock span { font-size: 12px; }
.touch .toast { font-size: 12px; padding: 5px 9px; }
.touch #prompt { font-size: 13px; padding: 6px 12px; bottom: calc(214px + env(safe-area-inset-bottom,0px)); }
.touch .dawn-card ul { font-size: 12px; }
.touch .dawn-card h3 { font-size: 15px; }
.touch .dawn-card .gbtn { padding: 8px 14px; font-size: 13px; }
.touch .sheet { max-height: 88%; }
.touch .tabs { min-height: 50px; }
.touch .tab { font-size: 14px; padding: 14px 12px; }
.touch .item { padding: 12px; }
.touch .item h3 { font-size: 15px; }
.touch .item p { font-size: 13px; }
.touch .buy { min-height: 44px; min-width: 56px; font-size: 14px; padding: 10px 14px; }
.touch .stepper .buy { min-width: 48px; font-size: 20px; }
.touch #closeBtn { min-height: 44px; }
.touch .perk { padding: 14px; }
.touch .perk b { font-size: 16px; }
.touch .perk span { font-size: 13px; }
@media (max-width: 520px) {
  .touch #mini { width: 90px; height: 90px; }
  .touch #campBtn { top: calc(110px + env(safe-area-inset-top,0px)); }
  .touch #sndBtn { top: calc(160px + env(safe-area-inset-top,0px)); }
  .touch #quests { top: calc(204px + env(safe-area-inset-top,0px)); width: min(170px, -210px + 100vw); font-size: 11px; }
  .touch #questList li small { display: none; }
  .touch #stats { min-width: 160px; }
  .touch #toasts { --toast-top: calc(214px + env(safe-area-inset-top,0px)); width: min(190px, 48vw); }
}
@media (pointer: coarse) and (max-height: 500px) {
  #stats { padding: 6px 8px; gap: 3px; font-size: 12px; }
  #mini { width: 70px; height: 70px; }
  .touch #campBtn { top: calc(86px + env(safe-area-inset-top,0px)); height: 38px; }
  .touch #sndBtn { top: calc(130px + env(safe-area-inset-top,0px)); height: 30px; font-size: 10px; }
  .touch #quests { top: calc(130px + env(safe-area-inset-top,0px)); }
  #clock { top: calc(8px + env(safe-area-inset-top,0px)); left: 50%; transform: translateX(-50%); }
  .touch #toasts { --toast-top: calc(150px + env(safe-area-inset-top,0px)); }
  .touch .btns { height: 160px; }
  .touch #act { width: 86px; height: 86px; }
  .touch #dashBtn { right: 94px; width: 58px; height: 58px; }
  .touch #wpnBtn { right: 14px; bottom: 94px; width: 54px; height: 54px; }
  .touch #potBtn { right: 82px; bottom: 72px; width: 50px; height: 50px; }
  .touch #atkBtn { right: 140px; bottom: 80px; width: 50px; height: 50px; }
  .touch #quests { top: calc(8px + env(safe-area-inset-top,0px)); right: calc(90px + env(safe-area-inset-right,0px)); width: 210px; }
  .touch #quests #questList { max-height: calc(-230px + 100vh); overflow-y: auto; }
}
@media (prefers-reduced-motion: reduce) {
  .toast { animation: auto ease 0s 1 normal none running none; }
}
